update.foreach:
MERGE INTO t_stock_price target USING dual ON (target.stock_code = #{item.stockCode} AND target.date_time = #{item.dateTime})
/* 1. 덮어쓰기 가드: 종목코드와 분시간이 완벽히 일치하는 기존 방이 존재한다면 최신 정산가로 오버라이딩 */ WHEN MATCHED THEN UPDATE SET target.price_open = #{item.priceOpen}, target.price_high = #{item.priceHigh}, target.price_low = #{item.priceLow}, target.price_close = #{item.priceClose}, target.volume = #{item.volume}
/* 2. 신규 장착 가드: 매칭되는 과거 타임라인이 전혀 없다면 순수 신규 분 봉으로 인서트 */ WHEN NOT MATCHED THEN INSERT ( target.stock_code, target.date_time, target.price_open, target.price_high, target.price_low, target.price_close, target.volume ) VALUES ( #{item.stockCode}, #{item.dateTime}, #{item.priceOpen}, #{item.priceHigh}, #{item.priceLow}, #{item.priceClose}, #{item.volume} );

mapper.select:
SELECT stock_code, date_time, price_open, price_high, price_low, price_close, volume FROM t_stock_price WHERE stock_code = #{stockCode}
AND date_time >= TO_DATE(#{dayString}, 'YYYYMMDD')
AND date_time < TO_DATE(#{dayString}, 'YYYYMMDD') + 1 ORDER BY date_time ASC
